// Built-in functions with argument validation
fn call_builtin(&mut self, name: &str, args: &[Expr]) -> Value {
    match name {
        "println" => {
            // println accepts any number of arguments
            for arg in args {
                println!("{}", self.eval_expr(arg).to_string());
            }
            Value::Null
        }

        "length" => {
            // length(x) - requires 1 argument
            if args.is_empty() {
                self.errors.push(RuntimeError::ArgumentError {
                    func: "length".to_string(),
                    expected: 1,
                    got: 0,
                });
                Value::Integer(0)
            } else if args.len() > 1 {
                self.errors.push(RuntimeError::ArgumentError {
                    func: "length".to_string(),
                    expected: 1,
                    got: args.len(),
                });
                Value::Integer(0)
            } else {
                match self.eval_expr(&args[0]) {
                    Value::Array(arr) => Value::Integer(arr.len() as i64),
                    Value::String(s) => Value::Integer(s.len() as i64),
                    v => {
                        self.errors.push(RuntimeError::TypeError {
                            expected: "array or string".to_string(),
                            got: v.to_string(),
                            context: "length() argument".to_string(),
                        });
                        Value::Integer(0)
                    }
                }
            }
        }

        "range" => {
            // range(start, end) - requires 2 arguments
            if args.len() < 2 {
                self.errors.push(RuntimeError::ArgumentError {
                    func: "range".to_string(),
                    expected: 2,
                    got: args.len(),
                });
                Value::Array(vec![])
            } else if args.len() > 2 {
                self.errors.push(RuntimeError::ArgumentError {
                    func: "range".to_string(),
                    expected: 2,
                    got: args.len(),
                });
                Value::Array(vec![])
            } else {
                let start = match self.eval_expr(&args[0]) {
                    Value::Integer(n) => n,
                    v => {
                        self.errors.push(RuntimeError::TypeError {
                            expected: "integer".to_string(),
                            got: v.to_string(),
                            context: "range() start argument".to_string(),
                        });
                        0
                    }
                };
                let end = match self.eval_expr(&args[1]) {
                    Value::Integer(n) => n,
                    v => {
                        self.errors.push(RuntimeError::TypeError {
                            expected: "integer".to_string(),
                            got: v.to_string(),
                            context: "range() end argument".to_string(),
                        });
                        0
                    }
                };

                let mut result = Vec::new();
                for i in start..end {
                    result.push(Value::Integer(i));
                }
                Value::Array(result)
            }
        }

        "str" => {
            // str(x) - requires 1 argument
            if args.is_empty() {
                self.errors.push(RuntimeError::ArgumentError {
                    func: "str".to_string(),
                    expected: 1,
                    got: 0,
                });
                Value::String(String::new())
            } else if args.len() > 1 {
                self.errors.push(RuntimeError::ArgumentError {
                    func: "str".to_string(),
                    expected: 1,
                    got: args.len(),
                });
                Value::String(String::new())
            } else {
                Value::String(self.eval_expr(&args[0]).to_string())
            }
        }

        _ => {
            self.errors.push(RuntimeError::UndefinedFunction(name.to_string()));
            Value::Null
        }
    }
}

