fn test_division_by_zero() {
    let mut executor = Executor::new();

    // 10 / 0 should record error
    let expr = Expr::BinOp {
        left: Box::new(Expr::Literal(Value::Integer(10))),
        op: "/".to_string(),
        right: Box::new(Expr::Literal(Value::Integer(0))),
    };

    let result = executor.eval_expr(&expr);

    // Should return safe default (0)
    assert_eq!(result, Value::Integer(0));

    // Should record error
    assert!(executor.has_errors());
    assert_eq!(executor.get_errors().len(), 1);

    println!("✓ Test 1: Division by zero detected");
}

