    assert!(executor.has_errors());
    println!("✓ Test 11: Invalid operator for types detected");
}

// ============================================================
// Test 12: Multiple Errors Accumulation
// ============================================================

#[test]
fn test_multiple_errors() {
    let mut executor = Executor::new();

    // Execute statements with multiple errors
    executor.exec_stmt(&Stmt::VarDecl {
        name: "x".to_string(),
        value: Expr::BinOp {
            left: Box::new(Expr::Literal(Value::Integer(10))),
            op: "/".to_string(),
            right: Box::new(Expr::Literal(Value::Integer(0))),  // Error 1: divide by zero
        },
    });

    executor.exec_stmt(&Stmt::VarDecl {
        name: "y".to_string(),
        value: Expr::Variable("undefined".to_string()),  // Error 2: undefined variable
    });

    executor.exec_stmt(&Stmt::VarDecl {
        name: "z".to_string(),
        value: Expr::FunctionCall {
            name: "unknown".to_string(),  // Error 3: undefined function
            args: vec![],
        },
    });

    // Should have recorded 3 errors
    assert!(executor.has_errors());
    assert_eq!(executor.get_errors().len(), 3);

    println!("✓ Test 12: Multiple errors accumulated");
}

// ============================================================
