    // Create struct without 'age' field
    let mut fields = std::collections::HashMap::new();
    fields.insert("name".to_string(), Expr::Literal(Value::String("Alice".to_string())));

    let struct_expr = Expr::StructConstruct {
        name: "Person".to_string(),
        fields,
    };

    let struct_val = executor.eval_expr(&struct_expr);

    // Try to access missing field
    let mut access_expr = std::collections::HashMap::new();
    access_expr.insert("age".to_string(), Expr::Literal(Value::Integer(30)));

    let result = executor.eval_expr(&Expr::FieldAccess {
        object: Box::new(Expr::Literal(struct_val)),
        field: "age".to_string(),
    });

    // Should record error for missing field
    assert!(executor.has_errors());
    println!("✓ Test 6: Missing struct field detected");
}

// ============================================================
// Test 7: Type Error - Array Append on Non-Array
// ============================================================

#[test]
fn test_append_to_non_array() {
    let mut executor = Executor::new();

    // Try to append to integer
    let expr = Expr::ArrayAppend {
        array: Box::new(Expr::Literal(Value::Integer(10))),
        item: Box::new(Expr::Literal(Value::Integer(20))),
    };

    let result = executor.eval_expr(&expr);

    // Should return null
    assert_eq!(result, Value::Null);

    // Should record error
    assert!(executor.has_errors());
    println!("✓ Test 7: Array append on non-array detected");
}

// ============================================================
// Test 8: Function Argument Count Error - Too Few
// ============================================================

#[test]
fn test_function_too_few_args() {
    let mut executor = Executor::new();

    // range() requires 2 args, provide 0
    let expr = Expr::FunctionCall {
        name: "range".to_string(),
        args: vec![],
    };

    let result = executor.eval_expr(&expr);

    // Should return empty array
    assert_eq!(result, Value::Array(vec![]));

    // Should record error
    assert!(executor.has_errors());
    println!("✓ Test 8: Function with too few arguments detected");
}

// ============================================================
// Test 9: Function Argument Count Error - Too Many
// ============================================================

#[test]
fn test_function_too_many_args() {
    let mut executor = Executor::new();

    // length() requires 1 arg, provide 2
    let expr = Expr::FunctionCall {
        name: "length".to_string(),
        args: vec![
            Expr::Literal(Value::Array(vec![])),
            Expr::Literal(Value::Integer(1)),
        ],
    };

    let result = executor.eval_expr(&expr);

    // Should return 0
    assert_eq!(result, Value::Integer(0));

    // Should record error
    assert!(executor.has_errors());
    println!("✓ Test 9: Function with too many arguments detected");
}

// ============================================================
// Test 10: Function Argument Type Error
// ============================================================

#[test]
fn test_function_arg_type_error() {
    let mut executor = Executor::new();

    // range() expects integers, provide strings
    let expr = Expr::FunctionCall {
        name: "range".to_string(),
        args: vec![
            Expr::Literal(Value::String("start".to_string())),
            Expr::Literal(Value::String("end".to_string())),
        ],
    };

    let result = executor.eval_expr(&expr);

    // Should still return array (with safe defaults)
    match result {
        Value::Array(_) => {}
        _ => panic!("Expected array result"),
    }

    // Should record errors for type mismatches
    assert!(executor.has_errors());
    println!("✓ Test 10: Function argument type error detected");
}

// ============================================================
// Test 11: Invalid Operator for Types
// ============================================================

#[test]
fn test_invalid_operator_for_types() {
    let mut executor = Executor::new();

    // Try to divide strings
    let expr = Expr::BinOp {
        left: Box::new(Expr::Literal(Value::String("hello".to_string()))),
        op: "/".to_string(),
        right: Box::new(Expr::Literal(Value::String("world".to_string()))),
    };

    let result = executor.eval_expr(&expr);

    // Should return null
    assert_eq!(result, Value::Null);

    // Should record error
    assert!(executor.has_errors());
    println!("✓ Test 11: Invalid operator for types detected");
}

// ============================================================
// Test 12: Multiple Errors Accumulation
// ============================================================

#[test]
fn test_multiple_errors() {
    let mut executor = Executor::new();

    // Execute statements with multiple errors
    executor.exec_stmt(&Stmt::VarDecl {
        name: "x".to_string(),
        value: Expr::BinOp {
            left: Box::new(Expr::Literal(Value::Integer(10))),
            op: "/".to_string(),
            right: Box::new(Expr::Literal(Value::Integer(0))),  // Error 1: divide by zero
        },
    });

    executor.exec_stmt(&Stmt::VarDecl {
        name: "y".to_string(),
        value: Expr::Variable("undefined".to_string()),  // Error 2: undefined variable
    });

    executor.exec_stmt(&Stmt::VarDecl {
        name: "z".to_string(),
        value: Expr::FunctionCall {
            name: "unknown".to_string(),  // Error 3: undefined function
            args: vec![],
        },
    });

    // Should have recorded 3 errors
    assert!(executor.has_errors());
    assert_eq!(executor.get_errors().len(), 3);

    println!("✓ Test 12: Multiple errors accumulated");
}

