// Test 13: Error Clear Functionality
// ============================================================

#[test]
fn test_error_clear() {
    let mut executor = Executor::new();

    // Generate an error
    let expr = Expr::BinOp {
        left: Box::new(Expr::Literal(Value::Integer(1))),
        op: "/".to_string(),
        right: Box::new(Expr::Literal(Value::Integer(0))),
    };

    executor.eval_expr(&expr);
    assert!(executor.has_errors());

    // Clear errors
    executor.clear_errors();
    assert!(!executor.has_errors());

    println!("✓ Test 13: Error clear works correctly");
}

// ============================================================
// Test 14: Execution Continues Despite Errors
// ============================================================

#[test]
fn test_execution_continues_after_error() {
    let mut executor = Executor::new();

    // Variable declaration that will error
    executor.exec_stmt(&Stmt::VarDecl {
        name: "result".to_string(),
        value: Expr::BinOp {
            left: Box::new(Expr::Literal(Value::Integer(5))),
            op: "/".to_string(),
            right: Box::new(Expr::Literal(Value::Integer(0))),
        },
    });

    // Should still have variable (with error value)
    assert!(executor.has_errors());

    // Another statement should execute
    executor.exec_stmt(&Stmt::VarDecl {
        name: "next".to_string(),
        value: Expr::Literal(Value::Integer(42)),
    });

    // Should have recorded the division by zero error
    let errors = executor.get_errors();
    assert!(errors.len() >= 1);

    println!("✓ Test 14: Execution continues after error");
}

