// Test 15: Error Message Quality
// ============================================================

#[test]
fn test_error_message_quality() {
    let mut executor = Executor::new();

    // Generate different error types
    executor.eval_expr(&Expr::Variable("x".to_string()));  // Undefined variable

    let errors = executor.get_errors();
    assert!(errors.len() > 0);

    // Check that error message is helpful
    let msg = errors[0].message();
    assert!(msg.contains("undefined"));
    assert!(msg.contains("x"));
    assert!(msg.contains("Hint"));  // Should have helpful hint

    println!("✓ Test 15: Error messages are helpful");
    println!("  Sample message: {}", msg);
}

