// Test 17: Error Report Formatting
// ============================================================

#[test]
fn test_error_report_formatting() {
    let mut executor = Executor::new();

    // Create multiple errors
    executor.eval_expr(&Expr::BinOp {
        left: Box::new(Expr::Literal(Value::Integer(1))),
        op: "/".to_string(),
        right: Box::new(Expr::Literal(Value::Integer(0))),
    });

    executor.eval_expr(&Expr::Variable("undefined".to_string()));

