use std::collections::HashMap;
use std::any::Any;

// ============================================================
// Runtime Error Types
// ============================================================

#[derive(Clone, Debug)]
pub enum RuntimeError {
    UndefinedVariable(String),
    UndefinedFunction(String),
    TypeError {
        expected: String,
        got: String,
        context: String,
    },
    DivisionByZero,
    ArgumentError {
        func: String,
        expected: usize,
        got: usize,
    },
    InvalidOperator {
        op: String,
        types: String,
    },
}

impl RuntimeError {
    /// Generate user-friendly error message
    pub fn message(&self) -> String {
        match self {
            RuntimeError::UndefinedVariable(name) => {
                format!("Error: undefined variable '{}'\nHint: declare it with 'var {} = value;'", name, name)
            }
            RuntimeError::UndefinedFunction(name) => {
                format!("Error: undefined function '{}()'\nHint: check function name and definition", name)
            }
            RuntimeError::TypeError { expected, got, context } => {
                format!(
                    "Error: type mismatch in {}\nExpected: {}\nGot: {}",
                    context, expected, got
                )
            }
            RuntimeError::DivisionByZero => {
                "Error: division by zero\nHint: check divisor is non-zero".to_string()
            }
            RuntimeError::ArgumentError { func, expected, got } => {
                format!(
                    "Error: function '{}()' expects {} argument(s), got {}\nHint: check function signature",
                    func, expected, got
                )
            }
            RuntimeError::InvalidOperator { op, types } => {
                format!(
                    "Error: operator '{}' cannot be applied to {} types",
                    op, types
                )
            }
        }
    }
}

// ============================================================
// Value Type (확장)
// ============================================================

#[derive(Clone, Debug)]
pub enum Value {
    Integer(i64),
    Boolean(bool),
    String(String),
    Array(Vec<Value>),
    Struct(HashMap<String, Value>),
    Function(String, Vec<String>), // function_name, params
    Null,
}

impl Value {
    pub fn to_string(&self) -> String {
        match self {
            Value::Integer(n) => n.to_string(),
            Value::Boolean(b) => b.to_string(),
            Value::String(s) => s.clone(),
            Value::Array(_) => "[Array]".to_string(),
            Value::Struct(_) => "{Struct}".to_string(),
            Value::Function(name, _) => format!("fn {}", name),
            Value::Null => "null".to_string(),
        }
    }

    pub fn is_truthy(&self) -> bool {
        match self {
            Value::Boolean(b) => *b,
            Value::Null => false,
            Value::Integer(0) => false,
            _ => true,
        }
    }
}

// ============================================================
// Runtime Environment
// ============================================================

pub struct Environment {
    variables: HashMap<String, Value>,
    functions: HashMap<String, String>, // function_name -> body
}

impl Environment {
    pub fn new() -> Self {
        Environment {
            variables: HashMap::new(),
            functions: HashMap::new(),
        }
    }

    pub fn get(&self, name: &str) -> Option<Value> {
        self.variables.get(name).cloned()
    }

    pub fn set(&mut self, name: String, value: Value) {
        self.variables.insert(name, value);
    }

    /// Set variable from &str reference (avoids clone of name string)
    pub fn set_ref(&mut self, name: &str, value: Value) {
        self.variables.insert(name.to_string(), value);
    }

    pub fn get_function(&self, name: &str) -> Option<String> {
        self.functions.get(name).cloned()
    }

    pub fn define_function(&mut self, name: String, body: String) {
        self.functions.insert(name, body);
    }
}

// ============================================================
// Expression Types
// ============================================================

#[derive(Clone, Debug)]
pub enum Expr {
    // Literals
    Literal(Value),

    // Variables
    Variable(String),

    // Binary Operations
    BinOp {
        left: Box<Expr>,
        op: String,
        right: Box<Expr>,
    },

    // Field Access: x.field
    FieldAccess {
        object: Box<Expr>,
        field: String,
    },

    // Function Call: fn_name(arg1, arg2)
    FunctionCall {
        name: String,
        args: Vec<Expr>,
    },

    // Array Append: arr + [item]
    ArrayAppend {
        array: Box<Expr>,
        item: Box<Expr>,
    },

    // Struct Constructor
    StructConstruct {
        name: String,
        fields: HashMap<String, Expr>,
    },
}

// ============================================================
// Statement Types
// ============================================================

#[derive(Clone, Debug)]
pub enum Stmt {
    // Variable Declaration: var x = expr
    VarDecl {
        name: String,
        value: Expr,
    },

    // Variable Assignment: x = expr
    Assign {
        name: String,
        value: Expr,
    },

    // For Loop: for i in range(0, 10) { ... }
    ForLoop {
        var: String,
        start: i64,
        end: i64,
        body: Vec<Stmt>,
    },

    // If Statement: if cond { ... } else { ... }
    If {
        condition: Expr,
        then_body: Vec<Stmt>,
        else_body: Option<Vec<Stmt>>,
    },

    // Return Statement
    Return(Option<Expr>),

    // Expression Statement
    Expr(Expr),
}

// ============================================================
// Executor
// ============================================================

pub struct Executor {
    env: Environment,
    return_value: Option<Value>,
    pub errors: Vec<RuntimeError>,  // Track errors without breaking execution
}

impl Executor {
    pub fn new() -> Self {
        Executor {
            env: Environment::new(),
            return_value: None,
            errors: Vec::new(),
        }
    }

    /// Check if any errors occurred
    pub fn has_errors(&self) -> bool {
        !self.errors.is_empty()
    }

    /// Get all recorded errors
    pub fn get_errors(&self) -> &[RuntimeError] {
        &self.errors
    }

    /// Clear error log (for test isolation)
    pub fn clear_errors(&mut self) {
        self.errors.clear();
    }

    /// Print formatted error report
    pub fn print_errors(&self) {
        if self.errors.is_empty() {
            return;
        }
        eprintln!("\n=== {} Runtime Error(s) ===\n", self.errors.len());
        for (idx, error) in self.errors.iter().enumerate() {
            eprintln!("[Error {}] {}\n", idx + 1, error.message());
        }
    }

    // Evaluate expression
    pub fn eval_expr(&mut self, expr: &Expr) -> Value {
        match expr {
            Expr::Literal(val) => val.clone(),

            Expr::Variable(name) => {
                match self.env.get(name) {
                    Some(val) => val,
                    None => {
                        // Record error for undefined variable
                        self.errors.push(RuntimeError::UndefinedVariable(name.clone()));
                        Value::Null
                    }
                }
            }

            Expr::BinOp { left, op, right } => {
                let lval = self.eval_expr(left);
                let rval = self.eval_expr(right);
                self.apply_binop(&lval, op, &rval)
            }

            Expr::FieldAccess { object, field } => {
                let obj_val = self.eval_expr(object);
                match obj_val {
                    Value::Struct(fields) => {
                        match fields.get(field) {
                            Some(val) => val.clone(),
                            None => {
                                self.errors.push(RuntimeError::TypeError {
                                    expected: format!("struct with field '{}'", field),
                                    got: "struct without field".to_string(),
                                    context: format!("field access '{}'", field),
                                });
                                Value::Null
                            }
                        }
                    }
                    _ => {
                        self.errors.push(RuntimeError::TypeError {
                            expected: "struct".to_string(),
                            got: obj_val.to_string(),
                            context: format!("field access '{}'", field),
                        });
                        Value::Null
                    }
                }
            }

            Expr::FunctionCall { name, args } => {
                self.call_builtin(name, args)
            }

            Expr::ArrayAppend { array, item } => {
                let arr_val = self.eval_expr(array);
                match arr_val {
                    Value::Array(mut arr) => {
                        let item_val = self.eval_expr(item);
                        arr.push(item_val);
                        Value::Array(arr)
                    }
                    _ => {
                        self.errors.push(RuntimeError::TypeError {
                            expected: "array".to_string(),
                            got: arr_val.to_string(),
                            context: "array append".to_string(),
                        });
                        Value::Null
                    }
                }
            }

            Expr::StructConstruct { name, fields } => {
                let mut struct_val = HashMap::new();
                for (k, v) in fields {
                    struct_val.insert(k.clone(), self.eval_expr(v));
                }
                Value::Struct(struct_val)
            }
        }
    }

    // Apply binary operators with error detection
    fn apply_binop(&mut self, left: &Value, op: &str, right: &Value) -> Value {
        match (left, right) {
            (Value::Integer(l), Value::Integer(r)) => {
                let result = match op {
                    "+" => l + r,
                    "-" => l - r,
                    "*" => l * r,
                    "/" => {
                        if *r != 0 {
                            l / r
                        } else {
                            self.errors.push(RuntimeError::DivisionByZero);
                            0  // Return safe default, but record error
                        }
                    }
                    "%" => {
                        if *r != 0 {
                            l % r
                        } else {
                            self.errors.push(RuntimeError::DivisionByZero);
                            0
                        }
                    }
                    "==" => return Value::Boolean(l == r),
                    "!=" => return Value::Boolean(l != r),
                    "<" => return Value::Boolean(l < r),
                    ">" => return Value::Boolean(l > r),
                    "<=" => return Value::Boolean(l <= r),
                    ">=" => return Value::Boolean(l >= r),
                    _ => {
                        self.errors.push(RuntimeError::InvalidOperator {
                            op: op.to_string(),
                            types: "integers".to_string(),
                        });
                        0
                    }
                };
                Value::Integer(result)
            }

            (Value::String(l), Value::String(r)) if op == "+" => {
                Value::String(format!("{}{}", l, r))
            }

            _ => {
                self.errors.push(RuntimeError::InvalidOperator {
                    op: op.to_string(),
                    types: format!("{} and {}", left.to_string(), right.to_string()),
                });
                Value::Null
            }
        }
    }

    // Built-in functions with argument validation
    fn call_builtin(&mut self, name: &str, args: &[Expr]) -> Value {
        match name {
            "println" => {
                // println accepts any number of arguments
                for arg in args {
                    println!("{}", self.eval_expr(arg).to_string());
                }
                Value::Null
            }

            "length" => {
                // length(x) - requires 1 argument
                if args.is_empty() {
                    self.errors.push(RuntimeError::ArgumentError {
                        func: "length".to_string(),
                        expected: 1,
                        got: 0,
                    });
                    Value::Integer(0)
                } else if args.len() > 1 {
                    self.errors.push(RuntimeError::ArgumentError {
                        func: "length".to_string(),
                        expected: 1,
                        got: args.len(),
                    });
                    Value::Integer(0)
                } else {
                    match self.eval_expr(&args[0]) {
                        Value::Array(arr) => Value::Integer(arr.len() as i64),
                        Value::String(s) => Value::Integer(s.len() as i64),
                        v => {
                            self.errors.push(RuntimeError::TypeError {
                                expected: "array or string".to_string(),
                                got: v.to_string(),
                                context: "length() argument".to_string(),
                            });
                            Value::Integer(0)
                        }
                    }
                }
            }

            "range" => {
                // range(start, end) - requires 2 arguments
                if args.len() < 2 {
                    self.errors.push(RuntimeError::ArgumentError {
                        func: "range".to_string(),
                        expected: 2,
                        got: args.len(),
                    });
                    Value::Array(vec![])
                } else if args.len() > 2 {
                    self.errors.push(RuntimeError::ArgumentError {
                        func: "range".to_string(),
                        expected: 2,
                        got: args.len(),
                    });
                    Value::Array(vec![])
                } else {
                    let start = match self.eval_expr(&args[0]) {
                        Value::Integer(n) => n,
                        v => {
                            self.errors.push(RuntimeError::TypeError {
                                expected: "integer".to_string(),
                                got: v.to_string(),
                                context: "range() start argument".to_string(),
                            });
                            0
                        }
                    };
                    let end = match self.eval_expr(&args[1]) {
                        Value::Integer(n) => n,
                        v => {
                            self.errors.push(RuntimeError::TypeError {
                                expected: "integer".to_string(),
                                got: v.to_string(),
                                context: "range() end argument".to_string(),
                            });
                            0
                        }
                    };

                    let mut result = Vec::new();
                    for i in start..end {
                        result.push(Value::Integer(i));
                    }
                    Value::Array(result)
                }
            }

            "str" => {
                // str(x) - requires 1 argument
                if args.is_empty() {
                    self.errors.push(RuntimeError::ArgumentError {
                        func: "str".to_string(),
                        expected: 1,
                        got: 0,
                    });
                    Value::String(String::new())
                } else if args.len() > 1 {
                    self.errors.push(RuntimeError::ArgumentError {
                        func: "str".to_string(),
                        expected: 1,
                        got: args.len(),
                    });
                    Value::String(String::new())
                } else {
                    Value::String(self.eval_expr(&args[0]).to_string())
                }
            }

            _ => {
                self.errors.push(RuntimeError::UndefinedFunction(name.to_string()));
                Value::Null
            }
        }
    }

    /// Execute statement - now tracks errors throughout execution
    pub fn exec_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::VarDecl { name, value } => {
                let val = self.eval_expr(value);
                self.env.set(name.clone(), val);
            }

            Stmt::Assign { name, value } => {
                let val = self.eval_expr(value);
                self.env.set(name.clone(), val);
            }

            Stmt::ForLoop { var, start, end, body } => {
                for i in *start..*end {
                    // Use set_ref to avoid cloning loop variable name
                    self.env.set_ref(var, Value::Integer(i));
                    for stmt in body {
                        self.exec_stmt(stmt);
                        // Continue executing even if errors occur
                        if self.return_value.is_some() {
                            break;  // Exit loop on return
                        }
                    }
                    if self.return_value.is_some() {
                        break;  // Exit loop on return
                    }
                }
            }

            Stmt::If { condition, then_body, else_body } => {
                let cond_val = self.eval_expr(condition);
                if cond_val.is_truthy() {
                    for stmt in then_body {
                        self.exec_stmt(stmt);
                        if self.return_value.is_some() {
                            break;  // Exit on return
                        }
                    }
                } else if let Some(els) = else_body {
                    for stmt in els {
                        self.exec_stmt(stmt);
                        if self.return_value.is_some() {
                            break;  // Exit on return
                        }
                    }
                }
            }

            Stmt::Return(Some(expr)) => {
                self.return_value = Some(self.eval_expr(expr));
            }

            Stmt::Return(None) => {
                self.return_value = Some(Value::Null);
            }

            Stmt::Expr(expr) => {
                let _ = self.eval_expr(expr);
            }
        }
    }
}

