// ============================================================
// Executor
// ============================================================

/// FreeLang expression and statement executor.
///
/// `Executor` evaluates expressions and executes statements, maintaining
/// runtime state and tracking errors. It supports:
/// - Variable declarations and access
/// - Binary operations with type checking
/// - Function calls with argument validation
/// - Struct literals and field access
/// - Array operations
/// - Control flow (if/else, for loops)
///
/// # Error Handling
///
/// The executor accumulates errors without stopping execution, allowing
/// comprehensive error reporting for partial code. Use `has_errors()`,
/// `get_errors()`, or `print_errors()` to check and report errors.
///
/// # Examples
///
/// ```
/// use freelang_compiler::{Executor, Stmt, Expr, Value};
///
/// let mut executor = Executor::new();
///
/// // Declare a variable
/// executor.exec_stmt(&Stmt::VarDecl {
///     name: "x".to_string(),
///     value: Expr::Literal(Value::Integer(5)),
/// });
///
/// // Check for errors
/// if executor.has_errors() {
///     executor.print_errors();
/// }
/// ```
pub struct Executor {
    env: Environment,
    return_value: Option<Value>,
    /// Runtime errors accumulated during execution
    pub errors: Vec<RuntimeError>,
}

impl Executor {
    /// Create a new executor with empty environment.
    ///
    /// # Examples
    ///
    /// ```
    /// use freelang_compiler::Executor;
    /// let mut executor = Executor::new();
    /// assert!(!executor.has_errors());
    /// ```
    pub fn new() -> Self {
        Executor {
            env: Environment::new(),
            return_value: None,
            errors: Vec::new(),
        }
    }

    /// Check if any errors occurred during execution.
    ///
    /// # Examples
    ///
    /// ```
    /// use freelang_compiler::{Executor, Expr, Value};
    ///
    /// let mut executor = Executor::new();
    /// // Reference undefined variable
    /// executor.eval_expr(&Expr::Variable("undefined".to_string()));
    /// assert!(executor.has_errors());
    /// ```
    pub fn has_errors(&self) -> bool {
        !self.errors.is_empty()
    }

    /// Get all recorded errors.
    ///
    /// Returns a slice of all errors that occurred during execution.
    /// Errors are preserved in order of occurrence.
    ///
    /// # Examples
    ///
    /// ```
    /// use freelang_compiler::{Executor, Expr};
    ///
    /// let mut executor = Executor::new();
    /// executor.eval_expr(&Expr::Variable("x".to_string()));
    /// assert_eq!(executor.get_errors().len(), 1);
    /// ```
    pub fn get_errors(&self) -> &[RuntimeError] {
        &self.errors
    }

    /// Clear all recorded errors.
    ///
    /// Useful for test isolation or starting fresh error tracking.
    ///
    /// # Examples
    ///
    /// ```
    /// use freelang_compiler::{Executor, Expr};
    ///
    /// let mut executor = Executor::new();
    /// executor.eval_expr(&Expr::Variable("x".to_string()));
    /// assert!(executor.has_errors());
    /// executor.clear_errors();
    /// assert!(!executor.has_errors());
    /// ```
    pub fn clear_errors(&mut self) {
        self.errors.clear();
    }

    /// Print formatted error report to stderr.
    ///
    /// Displays all accumulated errors with user-friendly messages and hints.
    /// Does nothing if no errors occurred.
    ///
    /// # Examples
    ///
    /// ```
    /// use freelang_compiler::{Executor, Expr};
    ///
    /// let mut executor = Executor::new();
    /// executor.eval_expr(&Expr::Variable("x".to_string()));
    /// executor.print_errors();  // Prints to stderr
    /// ```
    pub fn print_errors(&self) {
        if self.errors.is_empty() {
            return;
        }
        eprintln!("\n=== {} Runtime Error(s) ===\n", self.errors.len());
        for (idx, error) in self.errors.iter().enumerate() {
            eprintln!("[Error {}] {}\n", idx + 1, error.message());
        }
    }

