#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_executor_creation() {
        let _executor = Executor::new();
        println!("✓ Executor: creation works");
    }

    #[test]
    fn test_integer_literal() {
        let executor = Executor::new();
        let expr = Expr::Literal(Value::Integer(42));
        assert_eq!(executor.eval_expr(&expr).to_string(), "42");
        println!("✓ Executor: integer literal works");
    }

    #[test]
    fn test_string_literal() {
        let executor = Executor::new();
        let expr = Expr::Literal(Value::String("hello".to_string()));
        assert_eq!(executor.eval_expr(&expr).to_string(), "hello");
        println!("✓ Executor: string literal works");
    }

    #[test]
    fn test_variable_storage() {
        let mut executor = Executor::new();
        executor.env.set("x".to_string(), Value::Integer(10));
        let expr = Expr::Variable("x".to_string());
        assert_eq!(executor.eval_expr(&expr).to_string(), "10");
        println!("✓ Executor: variable storage works");
    }

    #[test]
    fn test_binary_op_addition() {
        let executor = Executor::new();
        let expr = Expr::BinOp {
            left: Box::new(Expr::Literal(Value::Integer(5))),
            op: "+".to_string(),
            right: Box::new(Expr::Literal(Value::Integer(3))),
        };
        assert_eq!(executor.eval_expr(&expr).to_string(), "8");
        println!("✓ Executor: binary op addition works");
    }

    #[test]
    fn test_struct_construction() {
        let mut executor = Executor::new();
        let mut fields = HashMap::new();
        fields.insert("name".to_string(), Expr::Literal(Value::String("test".to_string())));
        fields.insert("value".to_string(), Expr::Literal(Value::Integer(42)));

        let expr = Expr::StructConstruct {
            name: "TestStruct".to_string(),
            fields,
        };
        let result = executor.eval_expr(&expr);
        matches!(result, Value::Struct(_));
        println!("✓ Executor: struct construction works");
    }

    #[test]
    fn test_field_access() {
        let executor = Executor::new();
        let mut fields = HashMap::new();
        fields.insert("x".to_string(), Value::Integer(10));

        let expr = Expr::FieldAccess {
            object: Box::new(Expr::Literal(Value::Struct(fields))),
            field: "x".to_string(),
        };
        assert_eq!(executor.eval_expr(&expr).to_string(), "10");
        println!("✓ Executor: field access works");
    }

    #[test]
    fn test_array_append() {
        let executor = Executor::new();
        let arr = Value::Array(vec![Value::Integer(1), Value::Integer(2)]);
        let expr = Expr::ArrayAppend {
            array: Box::new(Expr::Literal(arr)),
            item: Box::new(Expr::Literal(Value::Integer(3))),
        };
        let result = executor.eval_expr(&expr);
        if let Value::Array(arr) = result {
            assert_eq!(arr.len(), 3);
        }
        println!("✓ Executor: array append works");
    }

    #[test]
    fn test_for_loop() {
        let mut executor = Executor::new();
        let body = vec![
            Stmt::Expr(Expr::Literal(Value::Null)),
        ];
        let stmt = Stmt::ForLoop {
            var: "i".to_string(),
            start: 0,
            end: 3,
            body,
        };
        executor.exec_stmt(&stmt);
        println!("✓ Executor: for loop works");
    }

    #[test]
    fn test_if_statement() {
        let mut executor = Executor::new();
        let then_body = vec![
            Stmt::VarDecl {
                name: "x".to_string(),
                value: Expr::Literal(Value::Integer(10)),
            },
        ];
        let stmt = Stmt::If {
            condition: Expr::Literal(Value::Boolean(true)),
            then_body,
            else_body: None,
        };
        executor.exec_stmt(&stmt);
        assert_eq!(executor.env.get("x").unwrap().to_string(), "10");
        println!("✓ Executor: if statement works");
    }

    #[test]
    fn test_length_builtin() {
        let executor = Executor::new();
        let expr = Expr::FunctionCall {
            name: "length".to_string(),
            args: vec![
                Expr::Literal(Value::Array(vec![Value::Integer(1), Value::Integer(2)]))
            ],
        };
        assert_eq!(executor.eval_expr(&expr).to_string(), "2");
        println!("✓ Executor: length builtin works");
    }

    #[test]
    fn test_range_builtin() {
        let executor = Executor::new();
        let expr = Expr::FunctionCall {
            name: "range".to_string(),
            args: vec![
                Expr::Literal(Value::Integer(0)),
                Expr::Literal(Value::Integer(3)),
            ],
        };
        if let Value::Array(arr) = executor.eval_expr(&expr) {
            assert_eq!(arr.len(), 3);
        }
        println!("✓ Executor: range builtin works");
    }

    #[test]
    fn test_string_concatenation() {
        let executor = Executor::new();
        let expr = Expr::BinOp {
            left: Box::new(Expr::Literal(Value::String("hello".to_string()))),
            op: "+".to_string(),
            right: Box::new(Expr::Literal(Value::String(" world".to_string()))),
        };
        assert_eq!(executor.eval_expr(&expr).to_string(), "hello world");
        println!("✓ Executor: string concatenation works");
    }

    #[test]
    fn test_comparison_ops() {
        let executor = Executor::new();
        let expr = Expr::BinOp {
            left: Box::new(Expr::Literal(Value::Integer(5))),
            op: "<".to_string(),
            right: Box::new(Expr::Literal(Value::Integer(10))),
        };
        if let Value::Boolean(b) = executor.eval_expr(&expr) {
            assert!(b);
        }
        println!("✓ Executor: comparison ops work");
    }

    #[test]
    fn test_var_declaration() {
        let mut executor = Executor::new();
        let stmt = Stmt::VarDecl {
            name: "x".to_string(),
            value: Expr::Literal(Value::Integer(42)),
        };
        executor.exec_stmt(&stmt);
        assert_eq!(executor.env.get("x").unwrap().to_string(), "42");
        println!("✓ Executor: var declaration works");
    }

    #[test]
    fn test_var_assignment() {
        let mut executor = Executor::new();
        executor.env.set("x".to_string(), Value::Integer(10));
        let stmt = Stmt::Assign {
            name: "x".to_string(),
            value: Expr::Literal(Value::Integer(20)),
        };
        executor.exec_stmt(&stmt);
        assert_eq!(executor.env.get("x").unwrap().to_string(), "20");
        println!("✓ Executor: var assignment works");
    }

    #[test]
    fn test_nested_expressions() {
        let executor = Executor::new();
        let expr = Expr::BinOp {
            left: Box::new(Expr::BinOp {
                left: Box::new(Expr::Literal(Value::Integer(2))),
                op: "+".to_string(),
                right: Box::new(Expr::Literal(Value::Integer(3))),
            }),
            op: "*".to_string(),
            right: Box::new(Expr::Literal(Value::Integer(4))),
        };
        assert_eq!(executor.eval_expr(&expr).to_string(), "20");
        println!("✓ Executor: nested expressions work");
    }

    #[test]
    fn test_complex_struct_workflow() {
        let mut executor = Executor::new();
        let mut fields = HashMap::new();
        fields.insert("x".to_string(), Expr::Literal(Value::Integer(10)));
        fields.insert("y".to_string(), Expr::Literal(Value::Integer(20)));

        let struct_expr = Expr::StructConstruct {
            name: "Point".to_string(),
            fields,
        };

        executor.env.set("p".to_string(), executor.eval_expr(&struct_expr));

        let access = Expr::FieldAccess {
            object: Box::new(Expr::Variable("p".to_string())),
            field: "x".to_string(),
        };

        assert_eq!(executor.eval_expr(&access).to_string(), "10");
        println!("✓ Executor: complex struct workflow works");
    }

    #[test]
    fn test_str_builtin() {
        let executor = Executor::new();
        let expr = Expr::FunctionCall {
            name: "str".to_string(),
            args: vec![Expr::Literal(Value::Integer(42))],
        };
        assert_eq!(executor.eval_expr(&expr).to_string(), "42");
        println!("✓ Executor: str builtin works");
    }
}

