// ============================================================
// FreeLang Executor - Basic Usage Examples
// ============================================================
// Phase 10 Stage 3: Documentation & Examples
//
// This file demonstrates basic usage patterns for the FreeLang
// executor, including variable operations, expressions, and
// error handling.

use freelang_compiler::{Executor, Expr, Stmt, Value};

fn main() {
    println!("╔═══════════════════════════════════════════════════════════╗");
    println!("║       FreeLang Executor - Basic Usage Examples            ║");
    println!("╚═══════════════════════════════════════════════════════════╝\n");

    example_1_hello_world();
    println!();
    example_2_variables_and_operations();
    println!();
    example_3_control_flow();
    println!();
    example_4_error_handling();
    println!();
    example_5_arrays_and_structs();
}

/// Example 1: Hello, World!
///
/// The simplest program - just printing a value.
fn example_1_hello_world() {
    println!("Example 1: Hello, World!");
    println!("─────────────────────────");

    let mut executor = Executor::new();

    // Call println with a string literal
    executor.eval_expr(&Expr::FunctionCall {
        name: "println".to_string(),
        args: vec![Expr::Literal(Value::String("Hello, World!".to_string()))],
    });

    if executor.has_errors() {
        executor.print_errors();
    } else {
        println!("✓ Success!\n");
    }
}

/// Example 2: Variables and Operations
///
/// Demonstrates variable declaration, assignment, and arithmetic.
fn example_2_variables_and_operations() {
    println!("Example 2: Variables and Operations");
    println!("──────────────────────────────────");

    let mut executor = Executor::new();

    // Declare x = 5
    executor.exec_stmt(&Stmt::VarDecl {
        name: "x".to_string(),
        value: Expr::Literal(Value::Integer(5)),
    });

    // Declare y = 3
    executor.exec_stmt(&Stmt::VarDecl {
        name: "y".to_string(),
        value: Expr::Literal(Value::Integer(3)),
    });

    // Evaluate x + y
    let result = executor.eval_expr(&Expr::BinOp {
        left: Box::new(Expr::Variable("x".to_string())),
        op: "+".to_string(),
        right: Box::new(Expr::Variable("y".to_string())),
    });

    println!("x = 5, y = 3");
    println!("x + y = {}", result.to_string());

    if !executor.has_errors() {
        println!("✓ Success!\n");
    } else {
        executor.print_errors();
    }
}

/// Example 3: Control Flow
///
/// Demonstrates if/else statements and for loops.
fn example_3_control_flow() {
    println!("Example 3: Control Flow");
    println!("──────────────────────");

    let mut executor = Executor::new();

    // Declare x = 10
    executor.exec_stmt(&Stmt::VarDecl {
        name: "x".to_string(),
        value: Expr::Literal(Value::Integer(10)),
    });

    // If x > 5: print "x is large"
    executor.exec_stmt(&Stmt::If {
        condition: Expr::BinOp {
            left: Box::new(Expr::Variable("x".to_string())),
            op: ">".to_string(),
            right: Box::new(Expr::Literal(Value::Integer(5))),
        },
        then_body: vec![Stmt::Expr(Expr::FunctionCall {
            name: "println".to_string(),
            args: vec![Expr::Literal(Value::String("x is large".to_string()))],
        })],
        else_body: Some(vec![Stmt::Expr(Expr::FunctionCall {
            name: "println".to_string(),
            args: vec![Expr::Literal(Value::String("x is small".to_string()))],
        })]),
    });

    // For loop: i from 0 to 3
    println!("\nFor loop: printing 0 to 3");
    executor.exec_stmt(&Stmt::ForLoop {
        var: "i".to_string(),
        start: 0,
        end: 3,
        body: vec![Stmt::Expr(Expr::FunctionCall {
            name: "println".to_string(),
            args: vec![Expr::Variable("i".to_string())],
        })],
    });

    if !executor.has_errors() {
        println!("✓ Success!\n");
    } else {
        executor.print_errors();
    }
}

/// Example 4: Error Handling
///
/// Demonstrates error detection and recovery.
fn example_4_error_handling() {
    println!("Example 4: Error Handling");
    println!("─────────────────────────");

    let mut executor = Executor::new();

    // Try to divide by zero
    println!("Attempting: 10 / 0");
    let _result = executor.eval_expr(&Expr::BinOp {
